import javax.swing.*;import java.awt.*;import java.util.*;
public class Main {static Set<String> registrations=new HashSet<>();public static void main(String[]a){SwingUtilities.invokeLater(()->{JFrame f=new JFrame("Campus Event Registration");JTextField reg=new JTextField(),name=new JTextField();JComboBox<String> event=new JComboBox<>(new String[]{"Tech Fest","AI Workshop","Sports Meet"});JLabel status=new JLabel("Not registered");JButton submit=new JButton("Register");submit.addActionListener(e->{String id=reg.getText().trim();if(id.isEmpty()||name.getText().isBlank()){status.setText("Enter all details");return;}if(!registrations.add(id+"-"+event.getSelectedItem())){status.setText("Already registered");return;}status.setText("Registration successful for "+name.getText());});f.setLayout(new GridLayout(0,2,6,6));f.add(new JLabel("Register no"));f.add(reg);f.add(new JLabel("Name"));f.add(name);f.add(new JLabel("Event"));f.add(event);f.add(submit);f.add(status);f.pack();f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setVisible(true);});}}
